"use client";

import { loadFont as loadHanken } from "@remotion/google-fonts/HankenGrotesk";
import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import type React from "react";
import { Fragment } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_DAYS,
  type LaunchDay,
  type LaunchDaysElementId,
  launchDaysList,
  launchDaysPicks,
  launchDaysTimeline,
} from "./timeline";

const hanken = loadHanken("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});
const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"] });
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

export interface LaunchDaysProps {
  week?: string;
  label?: string;
  days?: LaunchDay[];
  active?: number;
  from?: number;
  revealUpcoming?: boolean;
  logo?: React.ReactNode;
  accent?: string;
  background?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Typeface for the titles and copy. Load it yourself; Hanken Grotesk by default. */
  fontFamily?: string;
  /** Frames between title words as the active day writes in. */
  stagger?: number;
  /** Corner radius of the day cards, in px at 720p. */
  radius?: number;
  /** Size of the header and strip, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /**
   * Moves, trims or stretches the header, single cards, the open morph and
   * the title's words, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<LaunchDaysElementId>;
}

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    scrim: "rgba(10,10,11,0.84)",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    faint: "#55555C",
    panel: "rgba(255,255,255,0.03)",
    line: "rgba(255,255,255,0.08)",
    litLine: "rgba(255,255,255,0.14)",
    activeFg: "#F7F8FF",
    activeMuted: "rgba(236,240,255,0.74)",
    shade:
      "linear-gradient(180deg, rgba(4,6,20,0) 35%, rgba(4,6,20,0.55) 100%)",
    ground: "film-blue" as GshPresetId,
    groundParams: undefined as Partial<GradientParams> | undefined,
  },
  light: {
    bg: "#F5F4F0",
    scrim: "rgba(245,244,240,0.84)",
    fg: "#111113",
    muted: "#6E6C67",
    faint: "#A9A69E",
    panel: "rgba(255,255,255,0.5)",
    line: "rgba(17,17,19,0.08)",
    litLine: "rgba(17,17,19,0.1)",
    activeFg: "#0B0D1E",
    activeMuted: "rgba(11,13,30,0.68)",
    shade:
      "linear-gradient(180deg, rgba(245,246,252,0) 35%, rgba(245,246,252,0.6) 100%)",
    ground: "glasswork" as GshPresetId,
    groundParams: {
      colors: ["#a9bcff", "#3552ff", "#1a2a9e", "#7f9bff"],
    } as Partial<GradientParams> | undefined,
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.55, 0, 1, 0.45);
const SPRING_CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const SPRING_MORPH = { damping: 200 };
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

function estimateEm(text: string) {
  let w = 0;
  for (const ch of text) {
    if (ch === " ") w += 0.24;
    else if (/[ilIj.,'’!|]/.test(ch)) w += 0.25;
    else if (/[mwMW]/.test(ch)) w += 0.82;
    else if (/[A-Z]/.test(ch)) w += 0.64;
    else if (/[0-9]/.test(ch)) w += 0.55;
    else w += 0.52;
  }
  return w;
}

const pad2 = (n: number) => String(n).padStart(2, "0");

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export type { LaunchDay };

export function LaunchDays(props: LaunchDaysProps) {
  const {
    week = "Launch Week 01",
    label = "New today",
    days = DEFAULT_DAYS,
    active = 2,
    from,
    revealUpcoming = false,
    logo,
    accent = "#3B5BFD",
    background,
    ink,
    fontFamily = hanken.fontFamily,
    radius: corner = 16,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    ground,
    groundParams,
    timing,
  } = props;
  const glide = useGlide();
  const raw = Math.max(0, useSceneFrame() - delay);
  const frame = raw * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    launchDaysTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const p = PALETTES[theme];
  const fg = ink ?? p.fg;
  const activeFg = ink ?? p.activeFg;

  const list = launchDaysList(days);
  const n = list.length;
  const { act, swap } = launchDaysPicks(n, active, from);

  const portrait = height > width * 1.1;
  const u = Math.min(width, height) / 720;
  const margin = 40 * u;
  const marginX = portrait ? width * 0.07 : width * 0.1;
  const headerH = week || logo !== null ? 64 * u : 0;
  const gap = 8 * u;
  const radius = corner * u;

  const stripW = width - marginX * 2;
  const stripH = height - margin - headerH - margin * (headerH ? 0 : 1);
  const main = portrait ? stripH : stripW;
  const cross = portrait ? stripW : stripH;
  const sliver = Math.max(
    44 * u,
    Math.min((portrait ? 92 : 76) * u, main * 0.075),
  );
  const free = main - gap * (n - 1);
  const equal = free / n;
  const wide = free - sliver * (n - 1);

  const riseAt = (i: number, f: number) =>
    swap === null
      ? spring({
          frame: f - tl.get(`card:${i}`).start,
          fps,
          config: SPRING_CARD,
        })
      : 1;
  const rise = (i: number) => riseAt(i, frame);
  // The card's lift overshoots, so it is "moving" while its px still change.
  const lifting = (i: number) =>
    Math.abs(riseAt(i, frame + 1) - riseAt(i, frame)) * 30 * u > 1e-3 ||
    Math.abs(riseAt(i, frame) - riseAt(i, frame - 1)) * 30 * u > 1e-3;
  const openEl = tl.get("open");
  const open = spring({
    frame: frame - openEl.start,
    fps,
    config: SPRING_MORPH,
    durationInFrames: openEl.length,
  });
  const sizeAt = (i: number, o: number) => {
    if (swap === null) {
      return interpolate(o, [0, 1], [equal, i === act ? wide : sliver]);
    }
    const a = i === swap ? wide : sliver;
    const b = i === act ? wide : sliver;
    return interpolate(o, [0, 1], [a, b]);
  };
  const sizeOf = (i: number) => sizeAt(i, open);
  // Layout rounds every box edge to whole pixels, so cards pushed along by
  // their neighbours' widths, and labels centred in a card that narrows,
  // click across pixel by pixel. Each card is laid out where the morph
  // leaves it and travels there by a transform.
  const offsetAt = (i: number, o: number) => {
    let at = 0;
    for (let k = 0; k < i; k++) at += sizeAt(k, o) + gap;
    return at;
  };

  const eyebrowEl = tl.get("eyebrow");
  const eyebrowT = interpolate(
    frame,
    [eyebrowEl.start, eyebrowEl.end],
    [0, 1],
    { ...CLAMP, easing: EASE_OUT },
  );
  const wordT = (i: number) => {
    const e = tl.get(`word:${i}`);
    return interpolate(frame, [e.start, e.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  // Only with a swap: the day being swapped from writes out.
  const outT = (i: number) => {
    const e = tl.get("exit");
    const lag = i * e.beat("stagger");
    return interpolate(frame, [e.start + lag, e.end + lag], [0, 1], {
      ...CLAMP,
      easing: EASE_IN,
    });
  };

  const panelPad = (portrait ? 44 : 36) * u;
  const avail = (portrait ? cross : wide) - panelPad * 2;
  const base = (portrait ? 150 : 136) * u;
  const numFs = (portrait ? 150 : 112) * u;
  const titleFs = (title: string) => {
    const em = estimateEm(title);
    const one = avail / Math.max(em, 0.5);
    if (one >= base * 0.78) return Math.min(base, one);
    return Math.max(base * 0.5, Math.min(base * 0.86, (avail * 1.9) / em));
  };

  const transparent = background === "transparent";
  const showHeader = headerH > 0;
  const labelFs = 16 * u;
  const preset = ground ?? (groundParams ? undefined : p.ground);
  const litAt = openEl.start + openEl.beat("litAt");
  const litO = (i: number) =>
    i === act
      ? interpolate(frame, [litAt, litAt + openEl.beat("lit")], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        })
      : i === swap
        ? 1 -
          interpolate(
            frame,
            [openEl.start, openEl.start + openEl.beat("unlit")],
            [0, 1],
            { ...CLAMP, easing: EASE_IN },
          )
        : 0;
  const stripX = marginX;
  const stripY = showHeader ? headerH + margin * 0.15 : margin;
  const sizes = list.map((_, i) => sizeOf(i));
  const rectOf = (i: number) => {
    let at = 0;
    for (let k = 0; k < i; k++) at += (sizes[k] as number) + gap;
    const lift = (1 - rise(i)) * 30 * u;
    const sz = sizes[i] as number;
    return portrait
      ? { x: stripX, y: stripY + at + lift, w: stripW, h: sz }
      : { x: stripX + at, y: stripY + lift, w: sz, h: stripH - margin * 0.15 };
  };
  const rr = (x: number, y: number, w: number, h: number, r: number) =>
    `M${x + r} ${y}H${x + w - r}A${r} ${r} 0 0 1 ${x + w} ${y + r}V${y + h - r}A${r} ${r} 0 0 1 ${x + w - r} ${y + h}H${x + r}A${r} ${r} 0 0 1 ${x} ${y + h - r}V${y + r}A${r} ${r} 0 0 1 ${x + r} ${y}Z`;
  const holes = list
    .map((_, i) => i)
    .filter((i) => litO(i) > 0.001)
    .map((i) => {
      const q = rectOf(i);
      if (scale === 1) return rr(q.x, q.y, q.w, q.h, radius);
      // The cards sit in the ScaleLayer; the scrim doesn't, so map its holes.
      const sx = width / 2 + (q.x - width / 2) * scale;
      const sy = height / 2 + (q.y - height / 2) * scale;
      return rr(sx, sy, q.w * scale, q.h * scale, radius * scale);
    });
  const scrimD = `M0 0H${width}V${height}H0Z${holes.join("")}`;

  const headerEl = tl.get("header");
  const headerT = interpolate(frame, [headerEl.start, headerEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const renderOpen = (
    d: LaunchDay,
    i: number,
    mode: "in" | "out",
    size: number,
    carried: boolean,
  ) => {
    const fs = titleFs(d.title);
    const words = d.title.split(/\s+/).filter(Boolean);
    const shown = mode === "in";
    const eb = shown ? eyebrowT : 1 - outT(0);
    const numEl = tl.get("number");
    const descEl = tl.get("description");
    const numT = shown
      ? interpolate(frame, [numEl.start, numEl.end], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        })
      : 1 - outT(0);
    const descT = shown
      ? interpolate(frame, [descEl.start, descEl.end], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        })
      : 1 - outT(1);
    const box = portrait ? cross : wide;
    const contentOpacity = interpolate(
      size,
      [sliver * 1.2, sliver * 2.4],
      [0, 1],
      CLAMP,
    );
    return (
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: portrait ? box : wide,
          height: portrait ? wide : cross,
          padding: panelPad,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          opacity: contentOpacity,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "flex-start",
            justifyContent: "space-between",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 12 * u,
              marginTop: 6 * u,
              fontFamily: mono.fontFamily,
              fontWeight: 400,
              fontSize: labelFs * 1.1,
              letterSpacing: "0.08em",
              textTransform: "uppercase",
              color: activeFg,
              opacity: eb,
              transform: `translateX(${(1 - eb) * -16 * u}px)`,
            }}
          >
            <span>{d.day}</span>
            {label ? (
              <>
                <span
                  style={{
                    width: 22 * u,
                    height: 1,
                    background: p.activeMuted,
                    opacity: 0.6,
                  }}
                />
                <span style={{ color: p.activeMuted }}>{label}</span>
              </>
            ) : null}
          </div>
          <span
            style={{
              display: "inline-block",
              overflow: "hidden",
              paddingRight: "0.04em",
              marginTop: -numFs * 0.12,
              marginRight: -numFs * 0.02,
            }}
          >
            <span
              style={{
                display: "inline-block",
                fontFamily,
                fontWeight: 400,
                fontSize: numFs,
                lineHeight: 1,
                letterSpacing: "-0.05em",
                fontVariantNumeric: "tabular-nums",
                color: activeFg,
                transform: `translateY(${(1 - numT) * 100}%)${glide(!carried && midway(numT))}`,
              }}
            >
              {pad2(i + 1)}
            </span>
          </span>
        </div>
        <div>
          <div
            style={{
              fontFamily,
              fontWeight: 400,
              fontSize: fs,
              lineHeight: 0.98,
              letterSpacing: "-0.045em",
              color: activeFg,
              textWrap: "balance",
              marginLeft: -fs * 0.04,
            }}
          >
            {words.map((w, k) => {
              const t = shown ? wordT(k) : 1;
              const o = shown ? 0 : outT(k);
              return (
                <Fragment key={`${w}-${k}`}>
                  {k > 0 ? " " : null}
                  <span
                    style={{
                      display: "inline-block",
                      overflow: "hidden",
                      verticalAlign: "top",
                      paddingBottom: "0.12em",
                      marginBottom: "-0.12em",
                      paddingRight: "0.05em",
                      marginRight: "-0.05em",
                    }}
                  >
                    <span
                      style={{
                        display: "inline-block",
                        transform: `translateY(${(1 - t) * 105 - o * 105}%)${glide(!carried && (midway(t) || midway(o)))}`,
                      }}
                    >
                      {w}
                    </span>
                  </span>
                </Fragment>
              );
            })}
          </div>
          {d.description ? (
            <div
              style={{
                marginTop: fs * 0.26,
                maxWidth: Math.min(avail, 620 * u),
                fontFamily,
                fontWeight: 400,
                fontSize: (portrait ? 30 : 24) * u,
                lineHeight: 1.35,
                letterSpacing: "-0.01em",
                color: p.activeMuted,
                textWrap: "balance",
                opacity: descT,
                transform: `translateY(${(1 - descT) * 12 * u}px)${glide(!carried && midway(descT))}`,
                filter: `blur(${(1 - descT) * 5 * u}px)`,
              }}
            >
              {d.description}
            </div>
          ) : null}
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {transparent || background ? null : (
        <>
          <GshGround
            preset={preset}
            params={groundParams ?? (ground ? undefined : p.groundParams)}
            timeOffset={theme === "light" ? 4 : 2}
            timeScale={0.5}
          />
          <svg
            width={width}
            height={height}
            viewBox={`0 0 ${width} ${height}`}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <path d={scrimD} fill={p.scrim} fillRule="evenodd" />
          </svg>
        </>
      )}
      <ScaleLayer scale={scale}>
        {showHeader ? (
          <div
            style={{
              position: "absolute",
              left: marginX,
              right: marginX,
              top: 0,
              height: headerH + margin * 0.15,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              opacity: headerT,
              transform: `translateY(${(1 - headerT) * -8 * u}px)${glide(midway(headerT))}`,
            }}
          >
            <span
              style={{
                fontFamily: mono.fontFamily,
                fontWeight: 400,
                fontSize: labelFs * 1.1,
                letterSpacing: "0.08em",
                textTransform: "uppercase",
                color: fg,
              }}
            >
              {week}
            </span>
            {logo === null ? null : (
              <div style={{ display: "flex", alignItems: "center" }}>
                {logo ?? <RemocnLogo fontSize={24 * u} color={fg} />}
              </div>
            )}
          </div>
        ) : null}

        <div
          style={{
            position: "absolute",
            left: stripX,
            top: stripY,
            width: stripW,
            height: stripH - margin * 0.15,
            display: "flex",
            flexDirection: portrait ? "column" : "row",
            gap,
          }}
        >
          {list.map((d, i) => {
            const size = sizeOf(i);
            const r = rise(i);
            const isAct = i === act;
            const isFrom = i === swap;
            const groundO = litO(i);
            const past = i < act;
            const upcoming = i > act;
            const sliverTitle = upcoming && !revealUpcoming ? "" : d.title;
            const labelO = interpolate(
              size,
              [equal * 1.05, equal * 1.6],
              [1, 0],
              CLAMP,
            );
            const numColor = isAct ? activeFg : past ? fg : p.muted;
            const rest = sizeAt(i, 1);
            const atRest = offsetAt(i, 1);
            const slide = offsetAt(i, open) - atRest;
            const grow = (size - rest) / 2;
            const moving = lifting(i);
            return (
              <div
                key={`${d.day}-${i}`}
                style={{
                  position: "absolute",
                  [portrait ? "top" : "left"]: atRest,
                  [portrait ? "height" : "width"]: size,
                  [portrait ? "width" : "height"]: "100%",
                  borderRadius: radius,
                  overflow: "hidden",
                  background: groundO > 0.001 ? undefined : p.panel,
                  boxShadow: `inset 0 0 0 1px ${groundO > 0.5 ? p.litLine : p.line}`,
                  clipPath: `inset(${Math.max(0, 1 - r) * 100}% 0 0 0 round ${radius}px)`,
                  transform: `${
                    Math.abs(slide) < 1e-3
                      ? ""
                      : portrait
                        ? `translateY(${slide}px) `
                        : `translateX(${slide}px) `
                  }translateY(${(1 - r) * 30 * u}px)${glide(moving)}`,
                }}
              >
                {groundO > 0 ? (
                  <>
                    <div
                      style={{
                        position: "absolute",
                        inset: 0,
                        background: p.scrim,
                        opacity: 1 - groundO,
                      }}
                    />
                    <div
                      style={{
                        position: "absolute",
                        inset: 0,
                        background: p.shade,
                        opacity: groundO,
                      }}
                    />
                  </>
                ) : null}

                <div
                  style={{
                    position: "absolute",
                    // Centred across the width the card settles at; the
                    // narrowing on the way is a transform.
                    left: 0,
                    top: 0,
                    [portrait ? "width" : "height"]: "100%",
                    [portrait ? "height" : "width"]: rest,
                    boxSizing: "border-box",
                    transform:
                      Math.abs(grow) < 1e-3
                        ? undefined
                        : portrait
                          ? `translateY(${grow}px)${glide(midway(open) && !moving)}`
                          : `translateX(${grow}px)`,
                    padding: `${18 * u}px ${portrait ? 24 * u : 0}px`,
                    display: "flex",
                    flexDirection: portrait ? "row" : "column",
                    alignItems: portrait ? "center" : "center",
                    justifyContent: "space-between",
                    opacity: labelO * interpolate(r, [0.4, 1], [0, 1], CLAMP),
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      flexDirection: portrait ? "row" : "column",
                      alignItems: "center",
                      gap: 10 * u,
                    }}
                  >
                    <span
                      style={{
                        fontFamily: mono.fontFamily,
                        fontWeight: 400,
                        fontSize: labelFs * 1.15,
                        letterSpacing: "0.04em",
                        color: numColor,
                      }}
                    >
                      {pad2(i + 1)}
                    </span>
                    {past ? (
                      <span
                        style={{
                          width: 6 * u,
                          height: 6 * u,
                          borderRadius: 99,
                          background: accent,
                        }}
                      />
                    ) : null}
                  </div>
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 12 * u,
                      writingMode: portrait ? undefined : "vertical-rl",
                      transform: portrait ? undefined : "rotate(180deg)",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <span
                      style={{
                        fontFamily: mono.fontFamily,
                        fontWeight: 400,
                        fontSize: labelFs,
                        letterSpacing: "0.1em",
                        textTransform: "uppercase",
                        color: past ? p.muted : p.faint,
                      }}
                    >
                      {d.day}
                    </span>
                    {sliverTitle ? (
                      <span
                        style={{
                          fontFamily,
                          fontWeight: 400,
                          fontSize: labelFs * 1.6,
                          letterSpacing: "-0.02em",
                          color: past ? fg : p.muted,
                        }}
                      >
                        {sliverTitle}
                      </span>
                    ) : null}
                  </div>
                </div>

                {isAct ? renderOpen(d, i, "in", size, moving) : null}
                {isFrom ? renderOpen(d, i, "out", size, moving) : null}
              </div>
            );
          })}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The header fades down and the day cards rise one after another, then the
// active day's card opens wide and writes in: number, eyebrow, the title
// word by word, the description. With `from`, the cards stand from the start
// and the open day closes while the active one opens. Frames on the 30 fps
// scene timeline, after `delay` and `speed`. The ids are public: a saved
// `timing` prop refers to them.

export type LaunchDaysElementId =
  | "header"
  | `card:${number}`
  | "exit"
  | "open"
  | "number"
  | "eyebrow"
  | `word:${number}`
  | "description";

export interface LaunchDay {
  day: string;
  title: string;
  description?: string;
}

export interface LaunchDaysTimingProps {
  days?: LaunchDay[];
  active?: number;
  from?: number;
  stagger?: number;
}

export const DEFAULT_DAYS: LaunchDay[] = [
  {
    day: "Mon",
    title: "Captions",
    description: "31 transcript-driven caption styles.",
  },
  {
    day: "Tue",
    title: "Transitions",
    description: "Cuts that land on the beat.",
  },
  {
    day: "Wed",
    title: "Templates",
    description:
      "Whole launch films, installed into your project and yours to edit.",
  },
  {
    day: "Thu",
    title: "Agent skill",
    description: "Your agent reads the docs and picks the beat.",
  },
  {
    day: "Fri",
    title: "Studio",
    description: "Preview every scene before it renders.",
  },
];

const STAGGER = 3;
/** The card lift spring settles in this many frames. */
const RISE = 16;

/** The days on the strip: at least two, at most seven. */
export function launchDaysList(days: LaunchDay[]) {
  return days.length >= 2 ? days.slice(0, 7) : DEFAULT_DAYS;
}

/** The open day, and the day it swaps from (`null` without a swap). */
export function launchDaysPicks(n: number, active: number, from?: number) {
  const act = Math.min(Math.max(0, Math.round(active)), n - 1);
  const swap =
    from !== undefined && Math.round(from) !== act
      ? Math.min(Math.max(0, Math.round(from)), n - 1)
      : null;
  return { act, swap };
}

// `header` fades the header in. `card:<i>` lifts card `i` in, 2 frames
// after the one before; a chain (not with a swap: the cards stand). `exit`
// writes the day being swapped from out, its parts `stagger` apart (only
// with a swap). `open` morphs the strip over its length; the active card
// lights from `litAt` over `lit`, the swapped-from card goes dark over
// `unlit`. `number` and `eyebrow` fade in, `word:<k>` writes title word
// `k`, `stagger` after the one before; a chain. `description` follows.
export const launchDaysTimeline = defineTimeline<
  LaunchDaysElementId,
  LaunchDaysTimingProps
>(({ days = DEFAULT_DAYS, active = 2, from, stagger = STAGGER }) => {
  const list = launchDaysList(days);
  const { act, swap } = launchDaysPicks(list.length, active, from);
  const words = list[act].title.split(/\s+/).filter(Boolean);
  const elements: TimelineElement<LaunchDaysElementId>[] = [
    { id: "header", lane: "Header", label: "Header", start: 0, length: 18 },
  ];
  if (swap === null) {
    list.forEach((d, i) => {
      elements.push({
        id: `card:${i}`,
        lane: "Cards",
        label: d.day,
        start: i * 2,
        length: RISE,
        follows: i > 0 ? `card:${i - 1}` : undefined,
      });
    });
  } else {
    elements.push({
      id: "exit",
      lane: "Exit",
      label: list[swap].title,
      start: 6,
      length: 10,
      beats: { stagger: 2 },
    });
  }
  elements.push(
    {
      id: "open",
      lane: "Strip",
      label: list[act].day,
      start: 14,
      length: 28,
      beats: { litAt: 2, lit: 24, unlit: 22 },
    },
    { id: "number", lane: "Number", label: "Number", start: 24, length: 20 },
    { id: "eyebrow", lane: "Eyebrow", label: "Eyebrow", start: 26, length: 16 },
    ...words.map(
      (word, k): TimelineElement<LaunchDaysElementId> => ({
        id: `word:${k}`,
        lane: "Title",
        label: word,
        start: 30 + k * stagger,
        length: 18,
        follows: k > 0 ? `word:${k - 1}` : undefined,
      }),
    ),
    {
      id: "description",
      lane: "Description",
      label: list[act].description ?? "",
      start: 40 + words.length * 3,
      length: 20,
    },
  );
  return elements.sort((a, b) => a.start - b.start);
});
